 13	@Injectable()
 14	export class JobService {
 15	  constructor(
 16	    @Inject(PrismaService) private readonly prisma: PrismaService,
 17	    @Inject(JobScheduler) private readonly scheduler: JobScheduler,
 18	  ) {}
 19	
 20	  async create(
 21	    clientId: string,
 22	    command: string,
 23	    timeout?: number,
 24	  ): Promise<{ result: JobCreateResult; dispatch: DispatchPayload | null }> {
 25	    // Verify client exists and is online
 26	    const client = await this.prisma.client.findUnique({
 27	      where: { id: clientId },
 28	    });
 29	    if (!client) {
 30	      throw new Error(`Client "${clientId}" not found — register the client first`);
 31	    }
 32	    if (!client.online) {
 33	      throw new Error(`Client "${clientId}" is offline`);
 34	    }
 35	
 36	    const jobId = randomUUID();
 37	    await this.prisma.job.create({
 38	      data: {
 39	        id: jobId,
 40	        clientId,
 41	        command,
 42	        status: "pending",
 43	        timeout: timeout ?? null,
 44	      },
 45	    });
 46	
 47	    const dispatch = await this.scheduler.tryDispatch(clientId);
 48	
 49	    return {
 50	      result: {
 51	        jobId,
 52	        status: dispatch ? JobStatus.RUNNING : JobStatus.PENDING,
 53	      },
 54	      dispatch,
 55	    };
 56	  }
 57	
 58	  async appendOutputRaw(jobId: string, text: string) {
 59	    const job = await this.prisma.job.findUnique({ where: { id: jobId } });
 60	    if (!job) return;
 61	    await this.prisma.job.update({
 62	      where: { id: jobId },
 63	      data: { output: job.output + text },
 64	    });
 65	  }
