 82	  async markCancelled(jobId: string): Promise<DispatchPayload | null> {
 83	    const job = await this.prisma.job.update({
 84	      where: { id: jobId },
 85	      data: { status: "cancelled", finishedAt: new Date() },
 86	    });
 87	    return this.scheduler.onFinished(job.clientId);
