111	          await this.prisma.job.update({
112	            where: { id: r.jobId },
113	            data: { status: "running" },
114	          });
115	        }
116	      } else {
117	        const newStatus = r.status === "done" ? "done" : "error";
118	        await this.prisma.job.update({
119	          where: { id: r.jobId },
120	          data: {
121	            status: newStatus,
122	            exitCode: r.exitCode ?? 1,
123	            finishedAt: new Date(),
124	          },
125	        });
126	        const d = await this.scheduler.onFinished(clientId);
127	        if (d) dispatches.push(d);
128	      }
129	    }
130	
131	    return dispatches;
132	  }
